-- RS_MASTER_PATCH_20260922
ALTER TABLE clientes ADD COLUMN IF NOT EXISTS notas TEXT NULL;
ALTER TABLE clientes ADD COLUMN IF NOT EXISTS created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP;
ALTER TABLE clientes ADD COLUMN IF NOT EXISTS updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP;
ALTER TABLE pedidos ADD COLUMN IF NOT EXISTS cliente_id INT NULL;
ALTER TABLE pedidos ADD COLUMN IF NOT EXISTS descuento_id INT NULL;
ALTER TABLE pedidos ADD COLUMN IF NOT EXISTS descuento_monto DECIMAL(10,2) NOT NULL DEFAULT 0.00;
ALTER TABLE pedidos ADD COLUMN IF NOT EXISTS subtotal_antes_descuento DECIMAL(10,2) NULL;
ALTER TABLE descuentos ADD COLUMN IF NOT EXISTS minimo_compra DECIMAL(10,2) NOT NULL DEFAULT 0.00;
ALTER TABLE descuentos ADD COLUMN IF NOT EXISTS vigente_desde DATETIME NULL;
ALTER TABLE descuentos ADD COLUMN IF NOT EXISTS vigente_hasta DATETIME NULL;
CREATE TABLE IF NOT EXISTS inventario_articulos (
 id INT AUTO_INCREMENT PRIMARY KEY,nombre VARCHAR(150) NOT NULL,sku VARCHAR(80) NULL,categoria VARCHAR(100) NULL,unidad VARCHAR(30) NOT NULL DEFAULT 'pz',stock_actual DECIMAL(12,3) NOT NULL DEFAULT 0,stock_minimo DECIMAL(12,3) NOT NULL DEFAULT 0,stock_maximo DECIMAL(12,3) NULL,costo DECIMAL(12,2) NOT NULL DEFAULT 0,proveedor VARCHAR(150) NULL,ubicacion VARCHAR(150) NULL,activo BOOLEAN NOT NULL DEFAULT TRUE,notas TEXT NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,UNIQUE KEY uq_inventario_sku(sku),INDEX ix_inv_nombre(nombre),INDEX ix_inv_categoria(categoria));
CREATE TABLE IF NOT EXISTS inventario_movimientos (
 id BIGINT AUTO_INCREMENT PRIMARY KEY,articulo_id INT NOT NULL,tipo ENUM('entrada','salida','ajuste_positivo','ajuste_negativo','merma','devolucion','transferencia') NOT NULL,cantidad DECIMAL(12,3) NOT NULL,stock_anterior DECIMAL(12,3) NOT NULL,stock_nuevo DECIMAL(12,3) NOT NULL,motivo VARCHAR(255) NOT NULL,usuario VARCHAR(120) NOT NULL,referencia VARCHAR(120) NULL,notas TEXT NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY (articulo_id) REFERENCES inventario_articulos(id),INDEX ix_inv_mov_fecha(created_at),INDEX ix_inv_mov_articulo(articulo_id));
CREATE TABLE IF NOT EXISTS inventario_conteos (id BIGINT AUTO_INCREMENT PRIMARY KEY,usuario VARCHAR(120) NOT NULL,notas TEXT NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS inventario_conteo_items (id BIGINT AUTO_INCREMENT PRIMARY KEY,conteo_id BIGINT NOT NULL,articulo_id INT NOT NULL,stock_teorico DECIMAL(12,3) NOT NULL,stock_fisico DECIMAL(12,3) NOT NULL,diferencia DECIMAL(12,3) NOT NULL,FOREIGN KEY (conteo_id) REFERENCES inventario_conteos(id) ON DELETE CASCADE,FOREIGN KEY (articulo_id) REFERENCES inventario_articulos(id));
